import java.util.*;
public class Main {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(sc.nextInt());
        }
        int pos = sc.nextInt();
        Node head = n == 0 ? null : nodes[0];
        for (int i = 0; i + 1 < n; i++) {
            nodes[i].next = nodes[i + 1];
        }
        if (n > 0 && pos > 0) {
            nodes[n - 1].next = nodes[pos - 1];
        }
        Set<Node> seen = new HashSet<>();
        Node current = head;
        boolean cycle = false;
        while (current != null) {
            if (!seen.add(current)) {
                cycle = true;
                break;
            }
            current = current.next;
        }
        System.out.println(cycle ? "Cycle" : "No Cycle");
        sc.close();
    }
}
